import 'package:drift/drift.dart';

import '../../features/review/domain/flashcard.dart';
import '../../features/vocabulary/domain/vocabulary_entry.dart';

// Schema conventions:
// - Primary keys are UUID strings generated by the app (stable across devices).
// - All DateTime values are written in UTC (stored as ISO-8601 text).
// - Enums are stored by name; renaming a value requires a migration.
// - Language columns store ISO codes such as 'de' and 'fa'.

@DataClassName('DeckRow')
class Decks extends Table {
  TextColumn get id => text()();
  TextColumn get name => text().withLength(min: 1, max: 80)();
  TextColumn get sourceLanguage => text().withLength(min: 2, max: 16)();
  TextColumn get definitionLanguage => text().withLength(min: 2, max: 16)();
  // Drift's idiom for referencing the column inside its own definition.
  IntColumn get dailyNewCardLimit =>
      integer()
      // ignore: recursive_getters
      .check(dailyNewCardLimit.isBetweenValues(0, 1000))();
  DateTimeColumn get createdAt => dateTime()();
  DateTimeColumn get updatedAt => dateTime()();

  @override
  Set<Column<Object>> get primaryKey => {id};
}

@DataClassName('VocabularyEntryRow')
@TableIndex(
  name: 'idx_entries_deck_normalized',
  columns: {#deckId, #normalized},
)
class VocabularyEntries extends Table {
  TextColumn get id => text()();
  TextColumn get deckId =>
      text().references(Decks, #id, onDelete: KeyAction.cascade)();
  TextColumn get original => text().withLength(min: 1)();
  TextColumn get normalized => text()();
  TextColumn get lemma => text().nullable()();
  TextColumn get sourceLanguage => text().withLength(min: 2, max: 16)();
  TextColumn get definitionLanguage => text().withLength(min: 2, max: 16)();
  TextColumn get partOfSpeech => text().nullable()();
  TextColumn get exampleSentence => text().nullable()();
  TextColumn get exampleTranslation => text().nullable()();
  TextColumn get grammarInfo => text().nullable()();
  TextColumn get notes => text().nullable()();
  TextColumn get sourceContext => text().nullable()();
  TextColumn get sourceType => textEnum<VocabularySourceType>()();
  TextColumn get enrichmentStatus => textEnum<EnrichmentStatus>()();

  /// JSON-encoded `EnrichmentMetadata`.
  TextColumn get enrichmentMetadata => text().nullable()();
  DateTimeColumn get userEditedAt => dateTime().nullable()();
  DateTimeColumn get createdAt => dateTime()();
  DateTimeColumn get updatedAt => dateTime()();

  @override
  Set<Column<Object>> get primaryKey => {id};
}

/// Meanings live in their own table so an entry can have any number of them
/// in a stable order.
@DataClassName('VocabularyMeaningRow')
class VocabularyMeanings extends Table {
  TextColumn get id => text()();
  TextColumn get entryId =>
      text().references(VocabularyEntries, #id, onDelete: KeyAction.cascade)();
  IntColumn get position => integer()();
  TextColumn get meaning => text().withLength(min: 1)();
  TextColumn get explanation => text().nullable()();

  @override
  Set<Column<Object>> get primaryKey => {id};

  @override
  List<Set<Column<Object>>> get uniqueKeys => [
    {entryId, position},
  ];
}

/// Review scheduling state. Separate from vocabulary content on purpose:
/// updating an entry never touches this table.
@DataClassName('FlashcardRow')
@TableIndex(name: 'idx_flashcards_due', columns: {#due})
class Flashcards extends Table {
  TextColumn get id => text()();
  TextColumn get entryId =>
      text().references(VocabularyEntries, #id, onDelete: KeyAction.cascade)();
  TextColumn get direction => textEnum<CardDirection>()();
  TextColumn get state => textEnum<CardState>()();
  IntColumn get step => integer().nullable()();
  RealColumn get stability => real().nullable()();
  RealColumn get difficulty => real().nullable()();
  DateTimeColumn get due => dateTime()();
  DateTimeColumn get lastReviewedAt => dateTime().nullable()();
  IntColumn get reviewCount => integer().withDefault(const Constant(0))();
  IntColumn get lapseCount => integer().withDefault(const Constant(0))();
  TextColumn get schedulerVersion => text().nullable()();
  DateTimeColumn get createdAt => dateTime()();
  DateTimeColumn get updatedAt => dateTime()();

  @override
  Set<Column<Object>> get primaryKey => {id};

  @override
  List<Set<Column<Object>>> get uniqueKeys => [
    {entryId, direction},
  ];
}
